import re

def basic_quality_check(text, min_chars=80):
    stripped = text.strip()
    if len(stripped) < min_chars:
        return False
    if not re.search(r"[A-Za-z]", stripped):
        return False
    nonspace = [ch for ch in stripped if not ch.isspace()]
    if not nonspace:
        return False
    unusual_ratio = sum(not (ch.isalnum() or ch.isspace() or ch in ".,!?;:'\"-()[]{}_/+=#%&@") for ch in nonspace) / len(nonspace)
    return unusual_ratio < 0.35

print(basic_quality_check("This is an example of a readable document with useful text."))

import hashlib

def text_hash(text):
    normalized = " ".join(text.split())
    return hashlib.sha256(normalized.encode("utf-8")).hexdigest()

def exact_deduplicate(documents):
    seen = set()
    unique = []
    for document in documents:
        fingerprint = text_hash(document)
        if fingerprint not in seen:
            seen.add(fingerprint)
            unique.append(document)
    return unique

documents = ["AI learns patterns", "AI learns patterns", "Models learn from data"]
print(exact_deduplicate(documents))

def jaccard_similarity(a, b):
    a, b = set(a), set(b)
    union = a | b
    return len(a & b) / len(union) if union else 1.0

first = {"neural", "networks", "learn", "patterns"}
second = {"neural", "networks", "learn", "features"}
print(jaccard_similarity(first, second))
